# String the new entry (or the reason), Integer how many of the augment it takes, String the old entry (null = the slot is empty) }. Pure.
M(gaug, r"""
public static Object[] plan(String id, @BD@ d, int si, int k, int t) {
  if (!@PKG@.GearCfg.AUG_ON) return no("Augments are switched off on this server.");
  if (d == null) return no("The gear data of that item cannot be read.");
  if (!@PKG@.GearData.identified(d)) return no("Identify it first.");
  int w = kindAt(id, d);
  if (w <= 0) return no(@PKG@.Gear.itemName(id) + " cannot hold augments - weapons, armor and lifelong tools can.");
  if (w == 6 && @PKG@.GearLL.isRt(d)) return no(LLNOT);          // fix G3: a retired lifelong tool's perks never apply
  int n = slots(id, d);
  if (n <= 0) return no("It has no augment slot yet - add one with Add slot.");
  if (si < 0 || si >= n) return no("Pick one of its " + n + " slots first.");
  if (k < 0 || k >= TOP.length || t < 1 || t > TOP[k]) return no("Pick an augment first.");
  if (!fitsAt(k, w, id)) return no(KIND[k] + " augments fit " + fitText(k) + " only.");
  String[] e = raw(d);
  int[] q = entAt(e, si);
  if (q == null && occAt(e, si)) return no("Slot " + (si + 1) + " holds data this version cannot read - it is kept, so nothing can go there.");          // fix F3
  if (q == null) return new Object[] { Integer.valueOf(0), code(k, t), Integer.valueOf(1), null };
  String old = code(q[0], q[1]);
  if (q[0] == k && TYP[k] == 1) {
    if (q[1] == t) {
      if (t >= TOP[k]) return no(name(k, t) + " is the top tier - it cannot fuse higher.");
      int take = FUSE - 1;
      if (take < 1) take = 1;
      return new Object[] { Integer.valueOf(2), code(k, t + 1), Integer.valueOf(take), old };
    }
    if (t < q[1]) return no("That slot holds " + name(q[0], q[1]) + " - a lower " + KIND[k] + " augment would be a downgrade.");
  }
  if (q[0] == k && q[1] == t) return no("That slot already holds " + name(k, t) + ".");
  return new Object[] { Integer.valueOf(1), code(k, t), Integer.valueOf(1), old };
}""")
